    // supportsInterface must return true; the mutant will return false for at least one of those ids.
    function testFuzz_property(bytes4 interfaceId) public {
        // No tight assumptions; keep domain wide so fuzzer can hit the specific IERC1155 / IERC1155MetadataURI ids
        // Call supportsInterface and capture whether it completes (it won't revert) and the returned value
        bool ok;
