pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed parameters: an owner address and a token id and a mint quantity
    function testFuzz_property(address owner, uint256 tokenId, uint256 quantity) public {
        // keep owner non-zero (the contract requires non-zero for balanceOf and mint/burn logic)
        vm.assume(owner != address(0));
        // bound tokenId and quantity to reasonable ranges so we can create an item and mint
        uint256 id = tokenId % 10; // allow up to 10 different token types for the test
        uint256 qty = (quantity % 5) + 1; // mint between 1 and 5 tokens

        // Make caller an admin so we can create items and set burning addresses etc.
        // setUp used address(this) as owner, and isAdmin[address(this)] == true

        // create a game item with finiteSupply = false so minting isn't constrained by itemsRemaining
        c.createGameItem("itm", "uri", false, true, 0, 1, 1);

        // mint some tokens to the fuzzed owner by invoking internal _mint via contract's mint function
        // There is no public mint for ERC1155 except the internal one; but C.mint(tokenId, quantity) is public
        // and in this contract mints require tokenId < _itemCount which holds because we created at least one item
        // Ensure we mint to the owner by impersonating the owner
        vm.prank(address(this));
        // The contract's mint function mints to msg.sender, so to mint to owner we should impersonate owner and call mint
        vm.prank(owner);
        c.mint(id, qty);

        // Now check the stored balance returned by balanceOf(owner, id)
        uint256 reported = c.balanceOf(owner, id);

        // The general rule: after minting qty tokens to owner, balanceOf(owner,id) must equal qty
        // This holds for the reference implementation for all inputs; the mutant that always returns 0 will fail when qty > 0.
        assertTrue(reported == qty);
    }
}

