pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // General rule: after minting a positive quantity of tokenId to an account, balanceOf(account, tokenId) > 0.
    // The mutant always returns 0, so for some fuzzed inputs this will fail on the mutant but hold on the reference.
    function testFuzz_property(address to, uint256 tokenId, uint256 quantity) public {
        // Keep inputs admissible: to must not be zero address, quantity must be at least 1, tokenId bounded to avoid huge gas
        vm.assume(to != address(0));
        quantity = bound(quantity, 1, 10);
        tokenId = bound(tokenId, 0, 10);

        // Make caller an admin so createGameItem can be called from this contract
        // setUp made address(this) the owner/admin, so we can create items directly
        string memory name_ = "item";
        string memory tokenURI = "uri";
        bool finiteSupply = true;
        bool transferable = true;
        uint256 itemsRemaining = 100;
        uint256 itemPrice = 1;
        uint16 dailyAllowance = 1;

        // Create a game item at index 0.. using our fuzzed tokenId as desired index by creating up to tokenId
        // We ensure the array has at least tokenId+1 elements by creating items in a loop if needed
        uint256 existing = c.uniqueTokensOutstanding();
        if (existing <= tokenId) {
            for (uint256 i = existing; i <= tokenId; i++) {
                c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);
            }
        }

        // Mint the tokenId quantity to the fuzzed 'to' address by calling internal-like mint: contract has public mint(uint256,uint256)
        // C.mint is external and requires tokenId < _itemCount; we ensured that. Use vm.prank to act as the minter? Mint function in C doesn't restrict caller.
        // But C.mint requires caller to be any address (it is public), and it relies on Neuron instance for payment — however in C.mint it checks balance and transfers NRN; that path is the in-contract buy flow.
        // We can directly use ERC1155._mint by calling C._mint is internal; cannot. Instead, to obtain a stored non-zero balance, we'll call C.createGameItem then use C._mint indirectly by invoking C.mint which performs token purchase requiring NRN;
        // Simpler: use C as ERC1155 to mint by calling C.mint defined in C contract (it is the buy function). But it requires Neuron interaction; instead we can utilize C.createGameItem and then call C.safeTransferFrom from address(this) to 'to' after minting to address(this).
        // Strategy: create item and then use c.mint by simulating that msg.sender has enough NRN — but setting up Neuron is complex. Alternative: call c.createGameItem then call c._mint is impossible. However C contract inherits ERC1155 with public _mint? It's internal.
        // Workaround: deploy a small helper contract Holder that will call c.createGameItem (not needed) and then use c.mint? That's complex. Simpler approach: use c.createGameItem and then use c.safeTransferFrom to transfer tokens after minting them to address(this) via c.mint; but c.mint requires NRN.
        // New approach: exploit that C is our reference contract; we can call low-level self-call to invoke the internal _mint via a public function? There is no public wrapper. However we can make the contract itself be the recipient when creating an item? No.
        // Simpler practical way: call c.createGameItem then call c.mint won't work. Instead we can use burn/other functions? Burn requires allowedBurningAddresses.
        // Alternate method: use the fact that createGameItem emits nothing about balances. But ERC1155._mint is called in C._mint function only when c.mint purchase happens. To create a detectable non-zero balance using only public API, we can:
        // - createGameItem
        // - temporarily set isAdmin of 'to' and then call c.createGameItem? No.
        // Given constraints, a reliable way is to call c.createGameItem and then call c.mint but bypass NRN checks by deploying a fake Neuron and setting it via instantiateNeuronContract, so c.mint will interact with our fake Neuron to succeed.

        // Deploy a fake Neuron that will accept approveSpender and transferFrom and report sufficient balance
        FakeNeuron fake = new FakeNeuron();
        // instantiate c to use our fake Neuron
        c.instantiateNeuronContract(address(fake));

        // Ensure fake reports balance >= price and transferFrom returns true
        fake.setBalance(to, 100);
        fake.setTransferFromResult(true);

        // Now call c.mint from 'to' to buy quantity of tokenId; need to prank as 'to'
        vm.prank(to);
        c.mint(tokenId, quantity);

        // Now assert the general rule: after a successful mint to 'to', balanceOf(to, tokenId) > 0
        uint256 bal = c.balanceOf(to, tokenId);
        assertTrue(bal > 0);
    }
}

// Minimal fake Neuron to satisfy C.mint interactions
contract FakeNeuron {
    mapping(address => uint256) public balances;
    bool public transferResult = true;

    function setBalance(address who, uint256 amt) external { balances[who] = amt; }
    function setTransferFromResult(bool r) external { transferResult = r; }

    function balanceOf(address account) external view returns (uint256) { return balances[account]; }
    function approveSpender(address account, uint256 amount) external {}
    function transferFrom(address from, address to, uint256 amount) external returns (bool) { return transferResult; }
}

