pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz parameters: minter (as the caller performing the mint), recipient, tokenId, quantity
    function testFuzz_property(address minter, address recipient, uint256 tokenId, uint256 quantity) public {
        // admissible domain:
        // - recipient must not be zero address (balanceOf requires != 0)
        // - quantity must be > 0 (we want to observe a positive minted balance)
        // - tokenId must be bounded to avoid extremely large storage indexing but keep wide range
        vm.assume(recipient != address(0));
        vm.assume(quantity > 0);
        // keep tokenId reasonably bounded but allow wide variety
        tokenId = bound(tokenId, 0, 1000);

        // make caller the owner so it can create items and be admin
        // the constructor set isAdmin for address(this), but minter may be arbitrary; we will act via address(this)
        // create a game item with finiteSupply=false so minting isn't restricted by itemsRemaining
        string memory nm = "item";
        string memory uri = "uri";
        bool finiteSupply = false;
