// Minimal Neuron-compatible helper for the test: matches the subset C interacts with
contract SimpleNRN {
    mapping(address => uint256) public _balances;
    mapping(address => mapping(address => uint256)) public _allowances;

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }
    function approveSpender(address account, uint256 amount) external {
        _allowances[account][msg.sender] = amount;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (_allowances[from][msg.sender] < amount) return false;
        if (_balances[from] < amount) return false;
        _allowances[from][msg.sender] -= amount;
        _balances[from] -= amount;
        _balances[to] += amount;
        return true;
    }
